<?php
declare(strict_types=1);
namespace ReadyFinance;
final class HouseholdService {
 public function __construct(private Core $c){}
 public function setup(array $p):array{
  $c=$this->c;$locked=$c->query('SELECT GET_LOCK("readyfinance_setup",10)')->fetchColumn();if(!$locked)throw new Fault('Setup is busy. Try again.',409);try{return $c->atomic(function()use($c,$p){if($c->query('SELECT COUNT(*) FROM users')->fetchColumn()>0)throw new Fault('Setup is already complete.',409);$email=strtolower(Core::text($p['email']??'',190));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Fault('Enter a valid email.');$pass=(string)($p['password']??'');if(strlen($pass)<12||strlen($pass)>72)throw new Fault('Use a password of 12 to 72 characters.');$name=Core::text($p['name']??'');$h=$c->insert('households',['uuid'=>Core::uuid(),'name'=>Core::text($p['household']??''),'currency'=>'PKR','timezone'=>'Asia/Karachi','created_at'=>Core::now()]);$u=$c->insert('users',['uuid'=>Core::uuid(),'name'=>$name,'email'=>$email,'password_hash'=>password_hash($pass,PASSWORD_DEFAULT),'created_at'=>Core::now()]);$c->insert('household_memberships',['household_id'=>$h,'user_id'=>$u,'role'=>'owner']);$c->insert('members',['uuid'=>Core::uuid(),'household_id'=>$h,'name'=>$name,'relationship'=>'Self','created_at'=>Core::now()]);$c->ledger($h,'Opening equity','equity','opening_equity');$c->ledger($h,'Finance charges','expense','finance_expense');
   foreach(['expense'=>['Groceries','Dining','Housing','Utilities','Transport','Education','Health','Shopping','Giving','Other expenses'],'income'=>['Salary','Business drawings','Rent received','Other income']] as $type=>$names)foreach($names as $n){$lid=$c->ledger($h,$n,$type);$c->insert('categories',['uuid'=>Core::uuid(),'household_id'=>$h,'ledger_id'=>$lid,'name'=>$n,'type'=>$type]);}
   if((new AccountManagementService($c))->ready()){foreach(['income','expense'] as $type){$lid=$c->ledger($h,'Uncategorized '.$type,$type,'uncategorized_'.$type);$c->insert('categories',['uuid'=>Core::uuid(),'household_id'=>$h,'ledger_id'=>$lid,'name'=>'Uncategorized '.$type,'type'=>$type]);}}$c->audit($h,$u,'household.created',null);return ['user_id'=>$u,'household_id'=>$h];});}finally{$c->query('SELECT RELEASE_LOCK("readyfinance_setup")')->fetchColumn();}
 }
}
